import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"系统概述","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1794049926000}`),a={name:`overview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="系统概述" tabindex="-1">系统概述 <a class="header-anchor" href="#系统概述" aria-label="Permalink to “系统概述”">​</a></h1><p>本页说明部署形态、分层、请求路径与技术栈，适用于需要建立全局认识的开发者与架构评审者。</p><h2 id="部署形态" tabindex="-1">部署形态 <a class="header-anchor" href="#部署形态" aria-label="Permalink to “部署形态”">​</a></h2><p>单体部署、按能力包模块化：一个宿主进程（<code>XiHan.BasicApp.Host</code>）装配全部能力包，对外提供 HTTP API、内部 gRPC、MCP 与 SignalR Hub；前端是独立部署的单页应用。多租户、权限与审计贯穿所有包，不是某个模块的附属功能。</p><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to “分层”">​</a></h2><p>宿主与框架按环层组织，外层依赖内层：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ring 6  XiHan.BasicApp.Host             装配：Full Profile + 显式 Provider + 能力包；普通端点（文件、OAuth、Hub、Webhook）</span></span>
<span class="line"><span>        XiHan.BasicApp.&lt;能力包&gt;          Tier 0–3</span></span>
<span class="line"><span>Ring 5  Protocols.Http / Grpc / Mcp      一份操作登记，三种协议</span></span>
<span class="line"><span>Ring 4  Hosting.AspNetCore + Hosting.CommandLine（seed / schema upgrade / operations 等命令）</span></span>
<span class="line"><span>Ring 3  Persistence.SqlSugar、Security.Jwt、MultiTenancy.Database、Security.Database、</span></span>
<span class="line"><span>        Auditing.Database、Scheduling.Database、Workflow.Database、Localization.Database …</span></span>
<span class="line"><span>Ring 1  Kernel（操作、管道、Result / Error、消息目录）    Ring 0  Primitives</span></span></code></pre></div><p>能力包分四层，只能向下依赖、同层不互相引用；跨包协作经 <code>Contracts</code> 里的接口（如 <code>IWorkbenchWidgetProvider</code>、<code>ITenantQuota</code>、<code>IRealtimePush</code>）与消息主题：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Tier 0 基座       Contracts → Runtime</span></span>
<span class="line"><span>Tier 1 身份租户    Identity → Tenancy → Organization → Access</span></span>
<span class="line"><span>Tier 2 平台能力    Settings | Notification | Files | Auditing | Maintenance | OpenPlatform | Realtime</span></span>
<span class="line"><span>Tier 3 可选模块    Workbench | Workflow | Printing | CodeGeneration | Chat | AI</span></span>
<span class="line"><span>Host              XiHan.BasicApp.Host</span></span></code></pre></div><p>层级由 <code>XiHan.BasicApp.Architecture.Tests</code> 的 <code>TierDependencyTests</code> 守护。Tier 3 由 <code>BasicApp:Modules:&lt;名&gt;:Enabled</code> 开关，见<a href="./configuration#basicapp-modules">配置参考</a>。</p><h2 id="请求路径" tabindex="-1">请求路径 <a class="header-anchor" href="#请求路径" aria-label="Permalink to “请求路径”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器 ──HTTP──&gt; Kestrel ──&gt; 转发头 / 安全响应头 / 跨域 / 维护模式 / 认证 / 开放接口原文缓冲 ──&gt; UseXiHan()</span></span>
<span class="line"><span>                                                                    │</span></span>
<span class="line"><span>            内核管道：Ingress → Observe → Resilience → Authenticate → Tenant → Authorize</span></span>
<span class="line"><span>                      → Validate → Idempotency → Transaction → Handle → Egress</span></span>
<span class="line"><span>                                                                    │</span></span>
<span class="line"><span>                                        [Operation] HandleAsync → Result&lt;TResponse&gt;</span></span>
<span class="line"><span>                                                                    │</span></span>
<span class="line"><span>            成功：200 / 201 + 响应 DTO        失败：application/problem+json（code、detail、traceId、errors）</span></span></code></pre></div><p>各阶段里 BasicApp 贡献了哪些中间件（会话门禁、访问策略、权限条件、操作人、审计日志），见<a href="./backend/request-lifecycle">请求生命周期</a>。</p><h2 id="能力包一览" tabindex="-1">能力包一览 <a class="header-anchor" href="#能力包一览" aria-label="Permalink to “能力包一览”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>Tier</th><th>主要内容</th></tr></thead><tbody><tr><td><code>Contracts</code></td><td>0</td><td>实体基类与审计协议、分页 / 批量结果、权限描述、页面登记、跨包接口、消息主题、种子号段</td></tr><tr><td><code>Runtime</code></td><td>0</td><td>SqlSugar 回调、<code>TenantScopedQuery</code>、操作人、数据保护、表结构升级器、种子执行器、维护模式</td></tr><tr><td><code>Identity</code></td><td>1</td><td>登录（密码、验证码、第三方、双因素）、令牌与会话、锁屏、用户管理、在线用户、个人中心、模仿登录、用户设置</td></tr><tr><td><code>Tenancy</code></td><td>1</td><td>租户开通三步、独立库、套餐与配额、成员与所有权转移、我的订阅、切换租户</td></tr><tr><td><code>Organization</code></td><td>1</td><td>部门（闭包表）、岗位、部门成员</td></tr><tr><td><code>Access</code></td><td>1</td><td>角色与授权、Deny、继承、委托、数据范围、字段安全、权限条件、访问策略、约束规则、菜单</td></tr><tr><td><code>Settings</code></td><td>2</td><td>参数配置、字典、业务编号</td></tr><tr><td><code>Files</code></td><td>2</td><td>存储配置、文件与副本、秒传、分片上传、签名地址、导出中心、导入历史</td></tr><tr><td><code>Notification</code></td><td>2</td><td>通知公告、收件箱、消息模板、邮件 / 短信、群机器人、Telegram 机器人</td></tr><tr><td><code>Auditing</code></td><td>2</td><td>八类日志与链路追踪的查询面、日志写入队列、保留清理</td></tr><tr><td><code>Maintenance</code></td><td>2</td><td>任务调度、缓存管理、服务监控、版本与升级记录</td></tr><tr><td><code>OpenPlatform</code></td><td>2</td><td>签名开放接口、OAuth 2.0 / OIDC 服务端、OAuth 应用、我的应用、授权同意</td></tr><tr><td><code>Realtime</code></td><td>2</td><td>通知 Hub、连接与在线状态、按受众推送</td></tr><tr><td><code>Workbench</code></td><td>3</td><td>工作台小组件汇总（各包登记的指标、图表与列表）</td></tr><tr><td><code>Workflow</code></td><td>3</td><td>流程定义与实例、审批中心、审批业务接入</td></tr><tr><td><code>Printing</code></td><td>3</td><td>打印模板（平台全局与租户）、按编码解析、打印数据源目录</td></tr><tr><td><code>CodeGeneration</code></td><td>3</td><td>数据源、表结构导入、模板、代码生成、零代码只读运行时</td></tr><tr><td><code>Chat</code></td><td>3</td><td>单聊、群聊、部门群与助手会话、聊天 Hub、聊天审计、保留清理</td></tr><tr><td><code>AI</code></td><td>3</td><td>AI 提供商、提示词、知识库、助手</td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to “后端”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>选型</th></tr></thead><tbody><tr><td>运行时</td><td>.NET 10（<code>net10.0</code>，警告即错误、Nullable、代码风格在构建期执行）</td></tr><tr><td>框架</td><td>XiHan.Framework（<code>Profiles.Full</code>，ProjectReference 锁定提交）</td></tr><tr><td>数据</td><td>SqlSugar（框架 <code>Persistence.SqlSugar</code>），PostgreSQL 为缺省与 CI 口径</td></tr><tr><td>认证</td><td>框架 <code>Security.Jwt</code> 校验 HS256；签发、刷新、会话由 Identity 负责</td></tr><tr><td>实时</td><td>ASP.NET Core SignalR（<code>/hubs/notification</code>、<code>/hubs/chat</code>）</td></tr><tr><td>邮件 / 模板</td><td>MailKit、Scriban</td></tr><tr><td>接口文档</td><td>框架 OpenAPI 生成器 + Scalar</td></tr><tr><td>测试</td><td>xUnit（Microsoft.Testing.Platform）、TestServer + SQLite / PostgreSQL</td></tr></tbody></table><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to “前端”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>选型</th></tr></thead><tbody><tr><td>基础</td><td>Vue、Vite、TypeScript、Pinia、Vue Router（缺省 hash 模式）、vue-i18n</td></tr><tr><td>UI</td><td>XiHan.UI（<code>@xihan-ui/vue</code>、<code>headless</code>、<code>core</code>、<code>styles</code>、<code>tokens</code>、<code>icons</code> 等）、Tailwind CSS</td></tr><tr><td>契约</td><td><code>scripts/gen-contracts.mjs</code> 生成 <code>packages/contracts/*</code></td></tr><tr><td>实时</td><td><code>@microsoft/signalr</code></td></tr><tr><td>时间</td><td>dayjs（utc + timezone，按用户时区显示）</td></tr><tr><td>工具链</td><td>oxlint + eslint、Vitest + jsdom；Node.js 24+、pnpm 11+，没有锁文件</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li>先按<a href="./getting-started">快速开始</a>在本机运行，再读<a href="./project-structure">目录结构</a>。</li><li>后端从<a href="./backend/introduction">架构总览</a>与<a href="./backend/development">开发流程</a>开始，前端从<a href="./frontend/introduction">框架简介</a>开始。</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};